"""translate_to_english.py — one-shot: everything English (2026-07-02).

Covers: server.py (triage/assist/decom API strings), calib.html (UI strings),
7 tool docstrings, generate_inventory.py (English quick-ref + portable path),
RECALIBRATION_WORKFLOW.md (audit-tools section), then regenerates
TOOLS_INVENTORY.md. Idempotent — safe to re-run. Run from the repo root:
    python3 translate_to_english.py
"""
import os, subprocess, sys

def apply_pairs(path, pairs):
    s = open(path).read()
    n = 0
    for old, new in pairs:
        if old in s:
            s = s.replace(old, new, 1); n += 1
    open(path, 'w').write(s)
    print(f'{path}: {n}/{len(pairs)} strings translated (rest already EN)')

